Lemma rd_ek LB (sp os : Z) W M M1 :
  (forall i, 0 <= i < 2 ^ 64 -> ~ (sp - 48 <= i < sp - 48 + 48) -> ~ (os + 256 <= i < os + 256 + 40) -> M1 (Z_to_bv 64 i) = M (Z_to_bv 64 i)) ->
