Lemma call_resize (fx : FPState) R M model src x g sm cr (nn X : Z) :
  getr R (reg 1) = Z_to_bv 64 X -> L5.ra_ok X -> getr R (reg 2) = Z_to_bv 64 (S - 64) -> kept7 R ->
  getr R (reg 10) = Z_to_bv 64 ov -> getr R (reg 11) = Z_to_bv 64 nn ->
  0 <= nn < 2 ^ 64 -> PQV8.v8_grow_ok x nn ->
  state_ok M model src x g sm cr ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (x' : PQV8.v8) (g' : Z) (cr' : credit),
     regs_preserved R R' -> PQV8.v8_size x' = nn -> PQV8.v8_ok x' g' -> PQV8.v8_cap x <= PQV8.v8_cap x' ->
     (nn <= PQV8.v8_cap x -> PQV8.v8_own x' = PQV8.v8_own x /\ PQV8.v8_cap x' = PQV8.v8_cap x /\ g' = g) ->
     state_ok M' model' src x' g' sm cr' ->
     srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' X M' model') K) ->
