(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma call_fillw (fx : FPState) R M model src x g sm cr (b n c p X : Z) :
  getr R (reg 1) = Z_to_bv 64 X -> L5.ra_ok X -> getr R (reg 2) = Z_to_bv 64 (S - 64) -> kept7 R ->
  getr R (reg 10) = Z_to_bv 64 os -> getr R (reg 11) = Z_to_bv 64 p -> getr R (reg 12) = Z_to_bv 64 PM.CHUNK ->
  x = PQV8.V8Blk b n c -> b <= p -> p + PM.CHUNK <= b + c -> state_ok M model src x g sm cr ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (sm' : PM.strm) (d : Z),
     regs_preserved R R' -> getr R' (reg 10) = Z_to_bv 64 d -> 0 <= d <= PM.CHUNK -> PM.sm_g sm' = PM.sm_g sm + d ->
     (PM.sm_st sm = 0 -> d = Z.min PM.CHUNK (PM.sm_eg sm - PM.sm_g sm) /\ PM.sm_st sm' = (if Z.ltb d PM.CHUNK then 2 else 0)) ->
     (PM.sm_st sm = 2 -> d = 0 /\ PM.sm_st sm' = 2) ->
     PMSP.src_step src src sm sm' ->
     state_ok M' model src x g sm' cr ->
     srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' X M' model) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x47114 M model) K.
Proof using All.
