Definition lstate (R : bvmap 5 word) (M : word -> option byte) (model : Model) (src : PM.srcst) (x : PQV8.v8) (g : Z) (sm : PM.strm) (cr : credit) (w : Z) : Prop :=
  lregs R w /\ state_ok M model src x g sm cr /\ acct src x sm w /\ 1 <= w <= len /\ True.
Definition IHt (mu0 : Z) : Prop :=
  forall (fx : FPState) R M model src x g sm cr w, PM.mu_src src sm < mu0 -> lstate R M model src x g sm cr w ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x47230 M model) K.

