Lemma after_read mu0 (IH : IHt mu0) (fx : FPState) R M model src x g sm cr (w k d n : Z) :
  getr R (reg 2) = Z_to_bv 64 (S - 64) -> getr R (reg 8) = Z_to_bv 64 len -> getr R (reg 9) = Z_to_bv 64 ov ->
  getr R (reg 10) = Z_to_bv 64 d -> getr R (reg 18) = Z_to_bv 64 os -> getr R (reg 19) = Z_to_bv 64 16384 ->
  getr R (reg 20) = Z_to_bv 64 k -> getr R (reg 21) = Z_to_bv 64 w -> getr R (reg 22) = Z_to_bv 64 n -> kept7 R ->
  0 <= d <= k -> 1 <= k <= w -> k <= PM.CHUNK -> w <= len ->
  state_ok M model src x g sm cr -> PQV8.v8_size x = n + k -> n = len - w ->
  PMSP.consumed src0 src sm0 sm = len - w + d -> PMSP.src_step src0 src sm0 sm -> PM.mu_src src sm < mu0 ->
  (d = 0 -> PM.sr_rem src = 0 /\ PM.sm_st sm = 2) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x4729c M model) K.
Proof using All.
