  lregs R w -> getr R (reg 19) = Z_to_bv 64 16384 -> 16384 <= w <= len ->
  state_ok M model src x g sm cr -> acct src x sm w -> PM.sr_rem src = 0 -> PM.sm_st sm = 0 -> PM.mu_src src sm <= mu0 ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x472b0 M model) K.
Proof using All.
